        "text": "企业文化：阐述公司的使命（如“为客户提供优质放心的二手车及专业服务”）、愿景（如“成为行业内领先的二手车服务品牌”），以及独特的团队文化（如团结协作、创新进取、客户至上的工作氛围）。"
