    "desc": "严格的收购标准：制定严格的二手车收购标准，明确收购车辆的年限、里程、车况等要求，优先收购车况良好、无重大事故、无泡水、无火烧、无调表的车辆，从源头控制车源质量。",
    "type": "手册原文",
